import 'package:cloud_firestore/cloud_firestore.dart';
DateTime? _cDate(dynamic v)=>v is Timestamp?v.toDate():v is DateTime?v:null;Timestamp? _cStamp(DateTime? v)=>v==null?null:Timestamp.fromDate(v);
class ChildDoctor {final String id,name,specialty,photoUrl,address,phone;final double rating;final int reviewCount,experienceYears;final bool isVerified,isAvailable;final DateTime? createdAt,updatedAt;const ChildDoctor({required this.id,required this.name,required this.specialty,this.photoUrl='',this.rating=0,this.reviewCount=0,this.experienceYears=0,this.address='',this.phone='',this.isVerified=false,this.isAvailable=true,this.createdAt,this.updatedAt});factory ChildDoctor.fromFirestore(String id,Map<String,dynamic>d)=>ChildDoctor(id:id,name:'${d['name']??''}',specialty:'${d['specialty']??'أطفال'}',photoUrl:'${d['photoUrl']??''}',rating:(d['rating']as num?)?.toDouble()??0,reviewCount:(d['reviewCount']as num?)?.toInt()??0,experienceYears:(d['experienceYears']as num?)?.toInt()??0,address:'${d['address']??''}',phone:'${d['phone']??''}',isVerified:d['isVerified']==true,isAvailable:d['isAvailable']!=false,createdAt:_cDate(d['createdAt']),updatedAt:_cDate(d['updatedAt']));Map<String,dynamic>toFirestore()=>{'name':name,'specialty':specialty,'photoUrl':photoUrl,'rating':rating,'reviewCount':reviewCount,'experienceYears':experienceYears,'address':address,'phone':phone,'isVerified':isVerified,'isAvailable':isAvailable,'createdAt':_cStamp(createdAt),'updatedAt':_cStamp(updatedAt)};}
class ChildClinic {final String id,name,type,address,phone;final double rating;final bool isOpen;final GeoPoint? location;const ChildClinic({required this.id,required this.name,this.type='أطفال',this.address='',this.phone='',this.rating=0,this.isOpen=true,this.location});factory ChildClinic.fromFirestore(String id,Map<String,dynamic>d)=>ChildClinic(id:id,name:'${d['name']??''}',type:'${d['type']??'أطفال'}',address:'${d['address']??''}',phone:'${d['phone']??''}',rating:(d['rating']as num?)?.toDouble()??0,isOpen:d['isOpen']!=false,location:d['location']is GeoPoint?d['location']as GeoPoint:null);Map<String,dynamic>toFirestore()=>{'name':name,'type':type,'address':address,'phone':phone,'rating':rating,'isOpen':isOpen,'location':location};}
class ChildTip {final String id,title,body,category;final bool isPublished;final DateTime? createdAt;const ChildTip({required this.id,required this.title,required this.body,this.category='رضاعة',this.isPublished=true,this.createdAt});factory ChildTip.fromFirestore(String id,Map<String,dynamic>d)=>ChildTip(id:id,title:'${d['title']??''}',body:'${d['body']??''}',category:'${d['category']??'رضاعة'}',isPublished:d['isPublished']!=false,createdAt:_cDate(d['createdAt']));Map<String,dynamic>toFirestore()=>{'title':title,'body':body,'category':category,'isPublished':isPublished,'createdAt':_cStamp(createdAt)};}
class ChildHospital {final String id,name,address,phone;final bool emergency,isOpen;final GeoPoint? location;const ChildHospital({required this.id,required this.name,this.address='',this.phone='',this.emergency=false,this.isOpen=true,this.location});factory ChildHospital.fromFirestore(String id,Map<String,dynamic>d)=>ChildHospital(id:id,name:'${d['name']??''}',address:'${d['address']??''}',phone:'${d['phone']??''}',emergency:d['emergency']==true,isOpen:d['isOpen']!=false,location:d['location']is GeoPoint?d['location']as GeoPoint:null);Map<String,dynamic>toFirestore()=>{'name':name,'address':address,'phone':phone,'emergency':emergency,'isOpen':isOpen,'location':location};}
class ChildConsultation {final String id,userId,doctorId,question,status,answer;final DateTime? createdAt,answeredAt;const ChildConsultation({required this.id,required this.userId,this.doctorId='',required this.question,this.status='pending',this.answer='',this.createdAt,this.answeredAt});factory ChildConsultation.fromFirestore(String id,Map<String,dynamic>d)=>ChildConsultation(id:id,userId:'${d['userId']??''}',doctorId:'${d['doctorId']??''}',question:'${d['question']??''}',status:'${d['status']??'pending'}',answer:'${d['answer']??''}',createdAt:_cDate(d['createdAt']),answeredAt:_cDate(d['answeredAt']));Map<String,dynamic>toFirestore()=>{'userId':userId,'doctorId':doctorId,'question':question,'status':status,'answer':answer,'createdAt':_cStamp(createdAt),'answeredAt':_cStamp(answeredAt)};}
class ChildGrowthTracker {final String uid;final DateTime? birthDate;final double? height,weight;final List<Map<String,dynamic>> vaccinations;const ChildGrowthTracker({required this.uid,this.birthDate,this.height,this.weight,this.vaccinations=const []});factory ChildGrowthTracker.fromFirestore(String uid,Map<String,dynamic>d)=>ChildGrowthTracker(uid:uid,birthDate:_cDate(d['birthDate']),height:(d['height']as num?)?.toDouble(),weight:(d['weight']as num?)?.toDouble(),vaccinations:(d['vaccinations']as List? ?? const[]).whereType<Map>().map((e)=>Map<String,dynamic>.from(e)).toList());Map<String,dynamic>toFirestore()=>{'uid':uid,'birthDate':_cStamp(birthDate),'height':height,'weight':weight,'vaccinations':vaccinations};}
